#!/usr/bin/env Rscript
# Supplementary Figure S8. Evidence-layered candidate regulatory and communication networks.
# Edge evidence labels: 表达关联; 数据库先验; 候选配体–受体表达支持.
# All layers are hypothesis-generating and do not establish binding, secretion,
# receptor activation, or causal regulation.

suppressPackageStartupMessages({library(ggplot2);library(dplyr);library(readr);library(patchwork);library(grid);library(scales)})
args <- commandArgs(trailingOnly=FALSE); fa <- grep("^--file=",args,value=TRUE)
script_dir <- if(length(fa)) dirname(normalizePath(sub("^--file=","",fa[1]))) else file.path(getwd(),"graph")
root <- normalizePath(file.path(script_dir,"..",".."),mustWork=TRUE); outdir <- file.path(root,"submission_bmc_genomics","figures")
need <- function(x){if(!file.exists(x)) stop("Missing input: ",x); x}
tf_file <- need(file.path(root,"results/network_tf/mouse_tf_target_edges_top12.csv")); ppi_file <- need(file.path(root,"results/network_ppi/ppi_edges.csv")); lr_file <- need(file.path(root,"results/network_ligand_receptor/lr_top30_edges.csv")); integrated_file <- need(file.path(root,"results/network_integrated/integrated_edges.csv"))
ink <- "#243746"; muted <- "#687983"; edge_blue <- "#3B69A0"; ppi_grey <- "#6E7880"; lr_green <- "#2A9D8F"; core_red <- "#C4494B"; hub_blue <- "#3B69A0"
lr_cols <- c(epithelial_tumor="#D95F02",stellate="#7570B3",t_cell="#1B9E77")
theme_net <- theme_void(base_size=8,base_family="Arial Unicode MS") + theme(plot.title=element_text(colour=ink,face="bold",size=10.5,hjust=0,margin=margin(b=2)),plot.subtitle=element_text(colour=muted,size=7.2,hjust=0,margin=margin(b=4)),plot.tag=element_text(colour=ink,face="bold",size=11),plot.tag.position=c(.01,.995),plot.margin=margin(4,5,3,5))

## A: TF-target expression associations; top eight by descending score per TF.
tf_all <- read_csv(tf_file,show_col_types=FALSE) %>% mutate(tf=toupper(tf),target=toupper(target),edge_rank_score=as.numeric(edge_rank_score)) %>% group_by(tf) %>% arrange(desc(edge_rank_score),.by_group=TRUE) %>% slice_head(n=8) %>% ungroup()
if(nrow(tf_all)!=96L) warning("Expected 96 TF edges; found ",nrow(tf_all))
tf_levels <- sort(unique(tf_all$tf)); tf_xy <- tibble(tf=tf_levels,x=.08,y=seq(.08,.92,length.out=length(tf_levels)))
target_stats <- tf_all %>% group_by(target) %>% summarise(n=n(),max_score=max(edge_rank_score),.groups="drop") %>% arrange(desc(max_score),target) %>% mutate(x=.92,y=seq(.03,.97,length.out=n()))
tf_edges <- tf_all %>% left_join(tf_xy,by="tf") %>% rename(x_tf=x,y_tf=y) %>% left_join(target_stats %>% select(target,x,y),by="target") %>% rename(x_target=x,y_target=y)
target_labels <- target_stats %>% filter(n>=3)
p_a <- ggplot() + geom_segment(data=tf_edges,aes(x=x_tf,y=y_tf,xend=x_target,yend=y_target,alpha=rescale(edge_rank_score,to=c(.2,.72))),colour=edge_blue,linewidth=.33,arrow=arrow(length=unit(1.1,"mm"),type="closed")) + geom_point(data=tf_xy,aes(x,y),size=2.4,colour=edge_blue) + geom_point(data=target_stats,aes(x,y),size=1.45,colour="#9AA7AD") + geom_text(data=tf_xy,aes(x=x-.018,y=y,label=tf),hjust=1,colour=ink,size=2.3,fontface="bold") + geom_text(data=target_labels,aes(x=x+.018,y=y,label=target),hjust=0,colour=ink,size=1.85) + annotate("text",x=.08,y=.985,label="TF activity / expression",hjust=0,colour=muted,size=2.1) + annotate("text",x=.92,y=.985,label="target expression",hjust=1,colour=muted,size=2.1) + scale_alpha_identity() + coord_cartesian(xlim=c(0,1),ylim=c(0,1),clip="off") + labs(title="a  TF–target candidate associations",subtitle="Top 8/TF (96 edges); expression association + DoRothEA prior.") + theme_net

## B: STRING PPI prior; compact core-centred view at combined score >= 0.90.
core <- toupper(c("Txnip","Nlrp3","Casp1","Gsdmd","Il1b","Il18"))
ppi <- read_csv(ppi_file,show_col_types=FALSE) %>% mutate(from=toupper(from),to=toupper(to),combined_score=as.numeric(combined_score))
ppi_core <- ppi %>% filter(combined_score>=.90,from %in% core | to %in% core) %>% arrange(desc(combined_score),from,to)
ppi_nodes <- sort(unique(c(ppi_core$from,ppi_core$to))); core_present <- core[core %in% ppi_nodes]
if(nrow(ppi_core)!=37L) warning("Expected 37 compact PPI edges at score >= 0.90; found ",nrow(ppi_core))
core_xy <- tibble(name=core_present,angle=seq(0,2*pi,length.out=length(core_present)+1)[-(length(core_present)+1)]) %>% mutate(x=.50+.23*cos(angle),y=.51+.23*sin(angle)) %>% select(name,x,y)
noncore <- setdiff(ppi_nodes,core); noncore_xy <- tibble(name=noncore,angle=seq(0,2*pi,length.out=length(noncore)+1)[-(length(noncore)+1)]) %>% mutate(x=.50+.44*cos(angle),y=.51+.44*sin(angle)) %>% select(name,x,y)
ppi_xy <- bind_rows(core_xy,noncore_xy); ppi_plot_edges <- ppi_core %>% left_join(ppi_xy,by=c("from"="name")) %>% rename(x_from=x,y_from=y) %>% left_join(ppi_xy,by=c("to"="name")) %>% rename(x_to=x,y_to=y)
ppi_deg <- bind_rows(ppi_core %>% transmute(name=from),ppi_core %>% transmute(name=to)) %>% count(name); ppi_xy <- ppi_xy %>% left_join(ppi_deg,by="name") %>% mutate(is_core=name %in% core)
p_b <- ggplot() + geom_segment(data=ppi_plot_edges,aes(x=x_from,y=y_from,xend=x_to,yend=y_to,linewidth=combined_score),colour=ppi_grey,alpha=.52) + geom_point(data=ppi_xy,aes(x,y,size=ifelse(is_core,5.4,2.8),fill=is_core),shape=21,colour="white",stroke=.35) + geom_text(data=ppi_xy,aes(x=x+ifelse(x>.5,.018,-.018),y,label=name,hjust=ifelse(x>.5,0,1)),colour=ink,size=2.05,fontface=ifelse(ppi_xy$is_core,"bold","plain")) + scale_fill_manual(values=c("TRUE"=core_red,"FALSE"=hub_blue),guide="none") + scale_size_identity() + scale_linewidth(range=c(.35,1.35),guide="none") + coord_cartesian(xlim=c(.02,.98),ylim=c(.02,.98),clip="off") + labs(title="b  STRING PPI prior around the PRII core",subtitle="Core-centred STRING prior; score ≥ 0.90 (37 edges).") + theme_net

## C: sample-supported candidate macrophage ligand-receptor edges.
lr <- read_csv(lr_file,show_col_types=FALSE) %>% mutate(ligand=toupper(ligand),receptor=toupper(receptor),receiver=as.character(receiver),prevalence=as.numeric(prevalence),mean_score=as.numeric(mean_score)) %>% arrange(desc(prevalence),desc(mean_score),ligand,receptor,receiver) %>% slice_head(n=15)
ligands <- unique(lr$ligand); receptors <- unique(lr$receptor); receivers <- c("epithelial_tumor","stellate","t_cell")
lig_xy <- tibble(name=ligands,x=.24,y=seq(.11,.89,length.out=length(ligands))); rec_xy <- tibble(name=receptors,x=.59,y=seq(.08,.92,length.out=length(receptors))); recv_xy <- tibble(name=receivers,x=.90,y=c(.22,.50,.78))
lr_edges <- lr %>% left_join(lig_xy,by=c("ligand"="name")) %>% rename(x_ligand=x,y_ligand=y) %>% left_join(rec_xy,by=c("receptor"="name")) %>% rename(x_receptor=x,y_receptor=y) %>% left_join(recv_xy,by=c("receiver"="name")) %>% rename(x_receiver=x,y_receiver=y)
p_c <- ggplot() + geom_segment(data=lr_edges,aes(x=x_ligand,y=y_ligand,xend=x_receptor,yend=y_receptor,colour=receiver,linewidth=prevalence),alpha=.68,arrow=arrow(length=unit(1.3,"mm"),type="closed")) + geom_segment(data=lr_edges,aes(x=x_receptor,y=y_receptor,xend=x_receiver,yend=y_receiver,colour=receiver,linewidth=prevalence),alpha=.68,arrow=arrow(length=unit(1.3,"mm"),type="closed")) + geom_point(data=lig_xy,aes(x,y),size=2.7,colour=lr_green) + geom_point(data=rec_xy,aes(x,y),size=2.7,colour=lr_green) + geom_point(data=recv_xy,aes(x,y),size=3.2,shape=22,fill="#E5EEF0",colour=ink) + geom_text(data=lig_xy,aes(x=x-.017,y,label=name),hjust=1,size=2.15,colour=ink,fontface="bold") + geom_text(data=rec_xy,aes(x=x+.017,y,label=name),hjust=0,size=2.15,colour=ink) + geom_text(data=recv_xy,aes(x=x+.021,y,label=gsub("_"," ",name)),hjust=0,size=2.05,colour=ink) + annotate("text",x=.24,y=.985,label="Macrophage ligand",size=2.1,hjust=.5,colour=muted) + annotate("text",x=.59,y=.985,label="Receiver receptor",size=2.1,hjust=.5,colour=muted) + annotate("text",x=.90,y=.985,label="Receiver compartment",size=2.1,hjust=.5,colour=muted) + scale_colour_manual(values=lr_cols,name="Receiver") + scale_linewidth(range=c(.3,1.15),guide="none") + coord_cartesian(xlim=c(.02,1.02),ylim=c(.02,1),clip="off") + labs(title="c  Candidate macrophage ligand–receptor support",subtitle="Macrophage sender; top 15 recurrent edges; sample-level support (16 samples).") + theme_net + theme(legend.position="bottom",legend.title=element_text(size=6.5,colour=muted),legend.text=element_text(size=6),legend.key.width=unit(7,"mm"),legend.margin=margin(t=-2))

## D: evidence audit counts and operational definitions.
integrated <- read_csv(integrated_file,show_col_types=FALSE)
edge_levels <- c("TF-target (DoRothEA + expression)","STRING PPI","scRNA LR expression support")
edge_labels <- c("TF–target","STRING PPI","Ligand–receptor")
count_dat <- integrated %>% count(edge_type,name="n") %>% mutate(edge_type=factor(edge_type,levels=edge_levels)) %>% arrange(edge_type) %>% mutate(layer=edge_type,label=edge_labels[match(as.character(edge_type),edge_levels)])
if(nrow(count_dat)!=3L) stop("Integrated evidence table should contain three edge layers."); count_dat$x <- c(1,2,3)
p_d <- ggplot(count_dat,aes(x=x,y=n,fill=layer)) + geom_col(width=.62,colour="white",linewidth=.35) + geom_text(aes(label=n),vjust=-.35,fontface="bold",colour=ink,size=3.1) + scale_fill_manual(values=c("TF-target (DoRothEA + expression)"=edge_blue,"STRING PPI"=ppi_grey,"scRNA LR expression support"=lr_green),guide="none") + scale_x_continuous(breaks=count_dat$x,labels=count_dat$label,expand=expansion(mult=c(.13,.13))) + scale_y_continuous(limits=c(0,max(count_dat$n)*1.22),breaks=c(0,50,100,150),expand=c(0,0)) + labs(title="d  Evidence-layer audit",subtitle="Counts from integrated network; definitions in caption.",x=NULL,y="Number of selected edges") + theme_classic(base_size=8,base_family="Arial Unicode MS") + theme(plot.title=element_text(colour=ink,face="bold",size=10.5,margin=margin(b=2)),plot.subtitle=element_text(colour=muted,size=7.1,margin=margin(b=5)),axis.text.x=element_text(colour=ink,size=6.3,lineheight=.9),axis.text.y=element_text(colour=muted,size=6.5),axis.title.y=element_text(colour=muted,size=6.7),axis.line.x=element_line(colour="#89949A",linewidth=.35),axis.line.y=element_line(colour="#89949A",linewidth=.35),axis.ticks.x=element_blank(),panel.grid.major.y=element_line(colour="#E5EAEC",linewidth=.3),plot.tag=element_text(colour=ink,face="bold",size=11),plot.tag.position=c(.01,.995),plot.margin=margin(4,5,4,5))
fig6 <- (p_a|p_b)/(p_c|p_d) + plot_layout(widths=c(1.05,1),heights=c(1.08,1)) + plot_annotation(title="Supplementary Figure S8. Evidence-layered candidate regulatory and communication networks",subtitle="All edges are computationally inferred or database-supported and are hypothesis-generating.",theme=theme(plot.title=element_text(colour=ink,face="bold",size=13,hjust=0,margin=margin(b=2)),plot.subtitle=element_text(colour=muted,size=8.5,hjust=0,margin=margin(b=6)),plot.margin=margin(8,8,6,8),plot.background=element_rect(fill="white",colour=NA)))
pdf_out <- file.path(outdir,"FigS8_PRII_network.pdf"); tiff_out <- file.path(outdir,"FigS8_PRII_network.tiff")
ggsave(pdf_out,fig6,width=180,height=180,units="mm",device=cairo_pdf,bg="white",limitsize=FALSE)
tiff(tiff_out,width=180,height=180,units="mm",res=600,compression="lzw",type="cairo",bg="white"); print(fig6); dev.off()
write_csv(tf_all %>% mutate(evidence_label="表达关联;数据库先验"),file.path(outdir,"FigS8_PRII_network_TF_edges_top8.csv")); write_csv(ppi_core %>% mutate(evidence_label="数据库先验"),file.path(outdir,"FigS8_PRII_network_PPI_edges_core_score90.csv")); write_csv(lr %>% mutate(evidence_label="候选配体–受体表达支持"),file.path(outdir,"FigS8_PRII_network_LR_edges_top15.csv")); write_csv(count_dat %>% select(edge_type,n,label),file.path(outdir,"FigS8_PRII_network_evidence_counts.csv"))
cat("Wrote:\n",pdf_out,"\n",tiff_out,"\nTF edges=",nrow(tf_all),"; compact PPI edges=",nrow(ppi_core),"; LR edges=",nrow(lr),"; integrated edges=",nrow(integrated),"\n",sep="")
